<?= $this->section('contenido') ?>
<div class="container-fluid px-3 px-lg-4 py-4 df-pedidos df-cotizaciones"><header class="cot-cabecera"><div><p class="pedido-eyebrow">DELAFIBER / Configuración</p><h1 class="h4 fw-bold">Numeración de cotizaciones</h1></div><a href="<?= base_url('admin/cotizaciones') ?>" class="btn btn-light border">Volver</a></header>
    <section class="card pedido-card"><div class="card-body"><p class="small text-muted">Cada línea tiene su secuencia por año. El número inicial se usa si es mayor al último asignado; nunca se repiten números anteriores.</p><form class="cot-campos" method="post" action="<?= base_url('admin/cotizaciones/guardar-serie') ?>"><?= csrf_field() ?><div><label for="serieLinea" class="form-label">Línea</label><select id="serieLinea" name="idlinea" class="form-select" required><option value="">Selecciona</option><option value="0">Crear nueva línea</option><?php foreach ($series as $serie): ?><option value="<?= (int) $serie['idlinea'] ?>" data-prefijo="<?= esc($serie['prefijo_cotizacion'] ?? $serie['prefijo'], 'attr') ?>" data-inicial="<?= (int) ($serie['numero_inicial'] ?? 3571) ?>"><?= esc($serie['nombre']) ?></option><?php endforeach; ?></select></div><div id="nuevaLineaCotizacion" hidden><label class="form-label" for="nombreLineaCotizacion">Nombre de nueva línea</label><input class="form-control" id="nombreLineaCotizacion" name="nombre_linea" minlength="2" maxlength="60" disabled></div><div><label for="seriePrefijo" class="form-label">Prefijo</label><input id="seriePrefijo" name="prefijo" class="form-control" pattern="[A-Z0-9]{1,15}" maxlength="15" placeholder="CCTV" required></div><div><label for="serieInicial" class="form-label">Número inicial</label><input id="serieInicial" name="numero_inicial" class="form-control" type="number" min="1" max="999999999" step="1" value="3571" required></div><div class="cot-alinear"><button class="btn pedido-primary" type="submit">Guardar configuración</button></div></form><div class="table-responsive mt-4"><table class="table"><thead><tr><th>Línea</th><th>Prefijo</th><th>Inicio configurado</th></tr></thead><tbody><?php foreach ($series as $s): ?><tr><td><?= esc($s['nombre']) ?></td><td><?= esc($s['prefijo_cotizacion'] ?? 'Sin configurar') ?></td><td><?= $s['numero_inicial'] ? str_pad((string) $s['numero_inicial'], 6, '0', STR_PAD_LEFT) : '—' ?></td></tr><?php endforeach; ?></tbody></table></div></div></section>
</div>
