<?= $this->section('scripts') ?><script>document.getElementById('serieLinea').addEventListener('change', function () { const opcion = this.selectedOptions[0]; document.getElementById('seriePrefijo').value = opcion.dataset.prefijo || ''; document.getElementById('serieInicial').value = opcion.dataset.inicial || '3571'; const nueva = this.value === '0'; document.getElementById('nuevaLineaCotizacion').hidden = !nueva; document.getElementById('nombreLineaCotizacion').disabled = !nueva; document.getElementById('nombreLineaCotizacion').required = nueva; });</script><?= $this->endSection() ?>
